import{_ as o,o as t,c as a,a0 as d}from"./chunks/framework.OED5XGjC.js";const p=JSON.parse('{"title":"Command-Line Help for myco","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),c={name:"reference/cli.md"};function i(r,e,s,l,n,m){return t(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="command-line-help-for-myco" tabindex="-1">Command-Line Help for <code>myco</code> <a class="header-anchor" href="#command-line-help-for-myco" aria-label="Permalink to &quot;Command-Line Help for `myco`&quot;">​</a></h1><p>This document contains the help content for the <code>myco</code> command-line program.</p><p><strong>Command Overview:</strong></p><ul><li><a href="#myco"><code>myco</code>↴</a></li><li><a href="#myco-manifest"><code>myco manifest</code>↴</a></li><li><a href="#myco-schema"><code>myco schema</code>↴</a></li><li><a href="#myco-init"><code>myco init</code>↴</a></li><li><a href="#myco-check"><code>myco check</code>↴</a></li><li><a href="#myco-migrate"><code>myco migrate</code>↴</a></li><li><a href="#myco-commit"><code>myco commit</code>↴</a></li><li><a href="#myco-todo"><code>myco todo</code>↴</a></li><li><a href="#myco-todo-add"><code>myco todo add</code>↴</a></li><li><a href="#myco-todo-done"><code>myco todo done</code>↴</a></li><li><a href="#myco-todo-defer"><code>myco todo defer</code>↴</a></li><li><a href="#myco-todo-list"><code>myco todo list</code>↴</a></li><li><a href="#myco-backlog"><code>myco backlog</code>↴</a></li><li><a href="#myco-backlog-add"><code>myco backlog add</code>↴</a></li><li><a href="#myco-backlog-promote"><code>myco backlog promote</code>↴</a></li><li><a href="#myco-backlog-list"><code>myco backlog list</code>↴</a></li><li><a href="#myco-issue"><code>myco issue</code>↴</a></li><li><a href="#myco-issue-new"><code>myco issue new</code>↴</a></li><li><a href="#myco-issue-list"><code>myco issue list</code>↴</a></li><li><a href="#myco-issue-resolve"><code>myco issue resolve</code>↴</a></li><li><a href="#myco-issue-archive"><code>myco issue archive</code>↴</a></li><li><a href="#myco-issue-comment"><code>myco issue comment</code>↴</a></li><li><a href="#myco-proposal"><code>myco proposal</code>↴</a></li><li><a href="#myco-proposal-new"><code>myco proposal new</code>↴</a></li><li><a href="#myco-proposal-list"><code>myco proposal list</code>↴</a></li><li><a href="#myco-proposal-status"><code>myco proposal status</code>↴</a></li><li><a href="#myco-plan"><code>myco plan</code>↴</a></li><li><a href="#myco-plan-new"><code>myco plan new</code>↴</a></li><li><a href="#myco-plan-list"><code>myco plan list</code>↴</a></li><li><a href="#myco-adr"><code>myco adr</code>↴</a></li><li><a href="#myco-adr-new"><code>myco adr new</code>↴</a></li><li><a href="#myco-adr-list"><code>myco adr list</code>↴</a></li><li><a href="#myco-adr-supersede"><code>myco adr supersede</code>↴</a></li><li><a href="#myco-item"><code>myco item</code>↴</a></li><li><a href="#myco-item-show"><code>myco item show</code>↴</a></li><li><a href="#myco-item-set"><code>myco item set</code>↴</a></li><li><a href="#myco-handoff"><code>myco handoff</code>↴</a></li><li><a href="#myco-interrupt"><code>myco interrupt</code>↴</a></li><li><a href="#myco-resume"><code>myco resume</code>↴</a></li><li><a href="#myco-status"><code>myco status</code>↴</a></li><li><a href="#myco-board"><code>myco board</code>↴</a></li><li><a href="#myco-epic"><code>myco epic</code>↴</a></li><li><a href="#myco-milestone"><code>myco milestone</code>↴</a></li><li><a href="#myco-absorb"><code>myco absorb</code>↴</a></li><li><a href="#myco-absorb-comments"><code>myco absorb comments</code>↴</a></li><li><a href="#myco-absorb-jira"><code>myco absorb jira</code>↴</a></li><li><a href="#myco-absorb-github"><code>myco absorb github</code>↴</a></li><li><a href="#myco-report"><code>myco report</code>↴</a></li><li><a href="#myco-index"><code>myco index</code>↴</a></li><li><a href="#myco-index-add"><code>myco index add</code>↴</a></li><li><a href="#myco-index-remove"><code>myco index remove</code>↴</a></li><li><a href="#myco-index-list"><code>myco index list</code>↴</a></li><li><a href="#myco-index-rebuild"><code>myco index rebuild</code>↴</a></li><li><a href="#myco-org"><code>myco org</code>↴</a></li><li><a href="#myco-org-status"><code>myco org status</code>↴</a></li><li><a href="#myco-org-board"><code>myco org board</code>↴</a></li><li><a href="#myco-org-init"><code>myco org init</code>↴</a></li><li><a href="#myco-ui"><code>myco ui</code>↴</a></li><li><a href="#myco-serve"><code>myco serve</code>↴</a></li></ul><h2 id="myco" tabindex="-1"><code>myco</code> <a class="header-anchor" href="#myco" aria-label="Permalink to &quot;`myco`&quot;">​</a></h2><p>myco — project management, grown not built: agent-first PM CLI</p><p><strong>Usage:</strong> <code>myco [OPTIONS] &lt;COMMAND&gt;</code></p><h6 id="subcommands" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>manifest</code> — Capabilities + protocol version — agent self-discovery</li><li><code>schema</code> — The file/state spec, machine-readable JSON Schema</li><li><code>init</code> — Scaffold <code>project/</code>: orphan branch + worktree + .gitignore + seed files + the managed AGENTS.md agent-awareness block. Idempotent — existing worktree and AGENTS.md prose are preserved, only the marked block is (re)written</li><li><code>check</code> — Validate schemas + state machine, repair file/index drift; also validates the managed AGENTS.md block on the repo root. Exit 1 with findings; <code>--fix</code> applies safe repairs + commits</li><li><code>migrate</code> — Convert legacy ledgers to v2: <code>pm/</code> → <code>project/</code>, or normalize files already on the <code>project</code> branch</li><li><code>commit</code> — Stage + commit worktree changes (conventional message)</li><li><code>todo</code> — TODO.md tasks — add / done / defer / list</li><li><code>backlog</code> — BACKLOG.md parked items — add / promote / list</li><li><code>issue</code> — Tracked issues, one file each under <code>issues/</code></li><li><code>proposal</code> — Design proposals under <code>proposals/</code> (<code>P-NNN</code>)</li><li><code>plan</code> — Execution plans under <code>plans/</code> (<code>PL-NNN</code>)</li><li><code>adr</code> — Architecture decision records under <code>adrs/</code> (<code>ADR-NNNN</code>)</li><li><code>item</code> — Kind-agnostic item verbs — show / set</li><li><code>handoff</code> — Attach resumable state at session end — appends a dated entry to <code>handoffs/&lt;ID&gt;.md</code> (any item kind, live or archived; append-only)</li><li><code>interrupt</code> — A session ended with work still claimed/in-progress/ blocked — revert the item to <code>open</code> + <code>interrupted</code> handoff, one commit. Session-lifecycle hooks (sepia, CLI session-end) call this; myco never detects sessions itself</li><li><code>resume</code> — Minimal context block to restart work on an item — the item, <code>blocks:</code> dep titles, latest handoffs, open checklist. The single-item <code>status --prompt</code></li><li><code>status</code> — Cheap digest of the work ledger. <code>--prompt</code> = token-sized</li><li><code>board</code> — Kanban of the ledger — Backlog | Open | Claimed | In Progress | Blocked. <code>--md</code> emits a markdown table</li><li><code>epic</code> — Items grouped by epic — bare lists epics with counts, a name renders that epic&#39;s board (<code>epic v2</code> ≡ <code>board --epic v2</code>)</li><li><code>milestone</code> — Items grouped by milestone — bare lists milestones with counts, a name renders that milestone&#39;s board</li><li><code>absorb</code> — Import work into the ledger — TODO/FIXME comments, Jira CSV exports, GitHub issue dumps</li><li><code>report</code> — Aging + velocity + blocked — how the ledger is trending</li><li><code>index</code> — The derived index: register repos, query/rebuild snapshots</li><li><code>org</code> — Cross-repo views over the index (auto-rebuilds stale repos)</li><li><code>ui</code> — Interactive board TUI (ratatui) — TODO/BACKLOG tabs, item preview, writes through the same ops the verbs use</li><li><code>serve</code> — Sequential request/response verb surface on stdio — JSON-RPC 2.0, one line in / one line out. For embedding (peregrin spawns one per repo); stdin IS the wire, so no served method reads content from it</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON (accepted everywhere; default output for machines)</li><li><code>--no-commit</code> — Skip the per-verb commit (also suppressed by $MYCO_NO_COMMIT)</li><li><code>--dir &lt;PATH&gt;</code> — Project worktree to act on, overriding discovery</li><li><code>--root &lt;PATH&gt;</code> — Repo root to act on, overriding discovery (the worktree is <code>&lt;root&gt;/project</code>)</li></ul><h2 id="myco-manifest" tabindex="-1"><code>myco manifest</code> <a class="header-anchor" href="#myco-manifest" aria-label="Permalink to &quot;`myco manifest`&quot;">​</a></h2><p>Capabilities + protocol version — agent self-discovery</p><p><strong>Usage:</strong> <code>myco manifest</code></p><h2 id="myco-schema" tabindex="-1"><code>myco schema</code> <a class="header-anchor" href="#myco-schema" aria-label="Permalink to &quot;`myco schema`&quot;">​</a></h2><p>The file/state spec, machine-readable JSON Schema</p><p><strong>Usage:</strong> <code>myco schema</code></p><h2 id="myco-init" tabindex="-1"><code>myco init</code> <a class="header-anchor" href="#myco-init" aria-label="Permalink to &quot;`myco init`&quot;">​</a></h2><p>Scaffold <code>project/</code>: orphan branch + worktree + .gitignore + seed files + the managed AGENTS.md agent-awareness block. Idempotent — existing worktree and AGENTS.md prose are preserved, only the marked block is (re)written</p><p><strong>Usage:</strong> <code>myco init</code></p><h2 id="myco-check" tabindex="-1"><code>myco check</code> <a class="header-anchor" href="#myco-check" aria-label="Permalink to &quot;`myco check`&quot;">​</a></h2><p>Validate schemas + state machine, repair file/index drift; also validates the managed AGENTS.md block on the repo root. Exit 1 with findings; <code>--fix</code> applies safe repairs + commits</p><p><strong>Usage:</strong> <code>myco check [OPTIONS]</code></p><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--fix</code> — Repair drift in place instead of only reporting</li></ul><h2 id="myco-migrate" tabindex="-1"><code>myco migrate</code> <a class="header-anchor" href="#myco-migrate" aria-label="Permalink to &quot;`myco migrate`&quot;">​</a></h2><p>Convert legacy ledgers to v2: <code>pm/</code> → <code>project/</code>, or normalize files already on the <code>project</code> branch</p><p><strong>Usage:</strong> <code>myco migrate</code></p><h2 id="myco-commit" tabindex="-1"><code>myco commit</code> <a class="header-anchor" href="#myco-commit" aria-label="Permalink to &quot;`myco commit`&quot;">​</a></h2><p>Stage + commit worktree changes (conventional message)</p><p><strong>Usage:</strong> <code>myco commit [OPTIONS]</code></p><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>-m</code>, <code>--message &lt;MESSAGE&gt;</code> — Commit message (default: <code>chore: update project ledger</code>)</li></ul><h2 id="myco-todo" tabindex="-1"><code>myco todo</code> <a class="header-anchor" href="#myco-todo" aria-label="Permalink to &quot;`myco todo`&quot;">​</a></h2><p>TODO.md tasks — add / done / defer / list</p><p><strong>Usage:</strong> <code>myco todo &lt;COMMAND&gt;</code></p><h6 id="subcommands-1" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-1" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>add</code> — Add a task — allocs a T-id, appends to a section of TODO.md</li><li><code>done</code> — Mark done — walks the state machine to <code>done</code>, then removes the line (git history keeps the record). Done on a parent removes the whole subtree — children die with it</li><li><code>defer</code> — Park a task — transition to <code>deferred</code>, move the line to BACKLOG.md. Defer on a parent moves the whole subtree (children park with it); on a child it detaches alone</li><li><code>list</code> — List tasks</li></ul><h2 id="myco-todo-add" tabindex="-1"><code>myco todo add</code> <a class="header-anchor" href="#myco-todo-add" aria-label="Permalink to &quot;`myco todo add`&quot;">​</a></h2><p>Add a task — allocs a T-id, appends to a section of TODO.md</p><p><strong>Usage:</strong> <code>myco todo add [OPTIONS] &lt;TITLE&gt;</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TITLE&gt;</code> — One-line title</li></ul><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--section &lt;SECTION&gt;</code> — Section to add under (created when absent; default: the first section, or an unsectioned run)</li><li><code>--parent &lt;PARENT&gt;</code> — Nest under this task instead of a section — the new item becomes a child (<code> - [ ]</code> under the parent)</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id (<code>devin</code>, <code>human:luis</code>, …)</li><li><code>--label &lt;LABEL&gt;</code> — <code>#label</code> — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Ids this item blocks — comma-separated or repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — the delivery grouping this item belongs to (<code>[A-Za-z0-9_.-]+</code>)</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — the target this item ships under (<code>[A-Za-z0-9_.-]+</code>)</li></ul><h2 id="myco-todo-done" tabindex="-1"><code>myco todo done</code> <a class="header-anchor" href="#myco-todo-done" aria-label="Permalink to &quot;`myco todo done`&quot;">​</a></h2><p>Mark done — walks the state machine to <code>done</code>, then removes the line (git history keeps the record). Done on a parent removes the whole subtree — children die with it</p><p><strong>Usage:</strong> <code>myco todo done &lt;ID&gt;</code></p><h6 id="arguments-1" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-1" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Task id (<code>T-NNN</code>)</li></ul><h2 id="myco-todo-defer" tabindex="-1"><code>myco todo defer</code> <a class="header-anchor" href="#myco-todo-defer" aria-label="Permalink to &quot;`myco todo defer`&quot;">​</a></h2><p>Park a task — transition to <code>deferred</code>, move the line to BACKLOG.md. Defer on a parent moves the whole subtree (children park with it); on a child it detaches alone</p><p><strong>Usage:</strong> <code>myco todo defer &lt;ID&gt;</code></p><h6 id="arguments-2" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-2" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Task id (<code>T-NNN</code>)</li></ul><h2 id="myco-todo-list" tabindex="-1"><code>myco todo list</code> <a class="header-anchor" href="#myco-todo-list" aria-label="Permalink to &quot;`myco todo list`&quot;">​</a></h2><p>List tasks</p><p><strong>Usage:</strong> <code>myco todo list [OPTIONS]</code></p><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--status &lt;STATUS&gt;</code> — Keep only items with this status</li><li><code>--owner &lt;OWNER&gt;</code> — Keep only items owned by this actor</li><li><code>--label &lt;LABEL&gt;</code> — Keep only items carrying all of these labels (repeatable)</li><li><code>--limit &lt;N&gt;</code> — Keep only the first N items after filtering</li></ul><h2 id="myco-backlog" tabindex="-1"><code>myco backlog</code> <a class="header-anchor" href="#myco-backlog" aria-label="Permalink to &quot;`myco backlog`&quot;">​</a></h2><p>BACKLOG.md parked items — add / promote / list</p><p><strong>Usage:</strong> <code>myco backlog &lt;COMMAND&gt;</code></p><h6 id="subcommands-2" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-2" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>add</code> — Add a deferred item — allocs a T-id straight into BACKLOG.md</li><li><code>promote</code> — Re-activate a parked item — <code>deferred → open</code>, move the line to TODO.md</li><li><code>list</code> — List backlog items</li></ul><h2 id="myco-backlog-add" tabindex="-1"><code>myco backlog add</code> <a class="header-anchor" href="#myco-backlog-add" aria-label="Permalink to &quot;`myco backlog add`&quot;">​</a></h2><p>Add a deferred item — allocs a T-id straight into BACKLOG.md</p><p><strong>Usage:</strong> <code>myco backlog add [OPTIONS] &lt;TITLE&gt;</code></p><h6 id="arguments-3" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-3" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TITLE&gt;</code> — One-line title</li></ul><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--section &lt;SECTION&gt;</code> — Section to add under (created when absent; default: the first section, or an unsectioned run)</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id (<code>devin</code>, <code>human:luis</code>, …)</li><li><code>--label &lt;LABEL&gt;</code> — <code>#label</code> — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Ids this item blocks — comma-separated or repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — the delivery grouping this item belongs to (<code>[A-Za-z0-9_.-]+</code>)</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — the target this item ships under (<code>[A-Za-z0-9_.-]+</code>)</li></ul><h2 id="myco-backlog-promote" tabindex="-1"><code>myco backlog promote</code> <a class="header-anchor" href="#myco-backlog-promote" aria-label="Permalink to &quot;`myco backlog promote`&quot;">​</a></h2><p>Re-activate a parked item — <code>deferred → open</code>, move the line to TODO.md</p><p><strong>Usage:</strong> <code>myco backlog promote &lt;ID&gt;</code></p><h6 id="arguments-4" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-4" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Task id (<code>T-NNN</code>)</li></ul><h2 id="myco-backlog-list" tabindex="-1"><code>myco backlog list</code> <a class="header-anchor" href="#myco-backlog-list" aria-label="Permalink to &quot;`myco backlog list`&quot;">​</a></h2><p>List backlog items</p><p><strong>Usage:</strong> <code>myco backlog list [OPTIONS]</code></p><h6 id="options-6" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-6" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--status &lt;STATUS&gt;</code> — Keep only items with this status</li><li><code>--owner &lt;OWNER&gt;</code> — Keep only items owned by this actor</li><li><code>--label &lt;LABEL&gt;</code> — Keep only items carrying all of these labels (repeatable)</li><li><code>--limit &lt;N&gt;</code> — Keep only the first N items after filtering</li></ul><h2 id="myco-issue" tabindex="-1"><code>myco issue</code> <a class="header-anchor" href="#myco-issue" aria-label="Permalink to &quot;`myco issue`&quot;">​</a></h2><p>Tracked issues, one file each under <code>issues/</code></p><p><strong>Usage:</strong> <code>myco issue &lt;COMMAND&gt;</code></p><h6 id="subcommands-3" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-3" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>new</code> — File an issue — allocs an I-id, writes <code>issues/issue-NNNN-&lt;slug&gt;.md</code> with frontmatter + template</li><li><code>list</code> — List issues (live files; <code>--archived</code> includes <code>issues/archive/</code>)</li><li><code>resolve</code> — Close an issue — walks the state machine to <code>done</code>; <code>--resolution</code> appends text under <code>## Resolution</code></li><li><code>archive</code> — Shelve a done issue — moves the file to <code>issues/archive/</code></li><li><code>comment</code> — Append a dated note under <code>## Comments</code> (created when missing)</li></ul><h2 id="myco-issue-new" tabindex="-1"><code>myco issue new</code> <a class="header-anchor" href="#myco-issue-new" aria-label="Permalink to &quot;`myco issue new`&quot;">​</a></h2><p>File an issue — allocs an I-id, writes <code>issues/issue-NNNN-&lt;slug&gt;.md</code> with frontmatter + template</p><p><strong>Usage:</strong> <code>myco issue new [OPTIONS] &lt;TITLE&gt;</code></p><h6 id="arguments-5" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-5" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TITLE&gt;</code> — One-line title (drives the filename slug)</li></ul><h6 id="options-7" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-7" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--body &lt;FILE|-&gt;</code> — Body markdown from a file, or <code>-</code> for stdin</li><li><code>--text &lt;TEXT&gt;</code> — Body markdown inline</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id (<code>devin</code>, <code>human:luis</code>, …)</li><li><code>--label &lt;LABEL&gt;</code> — <code>#label</code> — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Ids this item blocks — comma-separated or repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — the delivery grouping this item belongs to (<code>[A-Za-z0-9_.-]+</code>)</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — the target this item ships under (<code>[A-Za-z0-9_.-]+</code>)</li></ul><h2 id="myco-issue-list" tabindex="-1"><code>myco issue list</code> <a class="header-anchor" href="#myco-issue-list" aria-label="Permalink to &quot;`myco issue list`&quot;">​</a></h2><p>List issues (live files; <code>--archived</code> includes <code>issues/archive/</code>)</p><p><strong>Usage:</strong> <code>myco issue list [OPTIONS]</code></p><h6 id="options-8" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-8" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--archived</code> — Include archived issues</li><li><code>--status &lt;STATUS&gt;</code> — Keep only items with this status</li><li><code>--owner &lt;OWNER&gt;</code> — Keep only items owned by this actor</li><li><code>--label &lt;LABEL&gt;</code> — Keep only items carrying all of these labels (repeatable)</li><li><code>--limit &lt;N&gt;</code> — Keep only the first N items after filtering</li></ul><h2 id="myco-issue-resolve" tabindex="-1"><code>myco issue resolve</code> <a class="header-anchor" href="#myco-issue-resolve" aria-label="Permalink to &quot;`myco issue resolve`&quot;">​</a></h2><p>Close an issue — walks the state machine to <code>done</code>; <code>--resolution</code> appends text under <code>## Resolution</code></p><p><strong>Usage:</strong> <code>myco issue resolve [OPTIONS] &lt;ID&gt;</code></p><h6 id="arguments-6" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-6" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Issue id (<code>I-NNN</code>)</li></ul><h6 id="options-9" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-9" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--resolution &lt;RESOLUTION&gt;</code> — Resolution text appended to the body</li></ul><h2 id="myco-issue-archive" tabindex="-1"><code>myco issue archive</code> <a class="header-anchor" href="#myco-issue-archive" aria-label="Permalink to &quot;`myco issue archive`&quot;">​</a></h2><p>Shelve a done issue — moves the file to <code>issues/archive/</code></p><p><strong>Usage:</strong> <code>myco issue archive &lt;ID&gt;</code></p><h6 id="arguments-7" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-7" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Issue id (<code>I-NNN</code>)</li></ul><h2 id="myco-issue-comment" tabindex="-1"><code>myco issue comment</code> <a class="header-anchor" href="#myco-issue-comment" aria-label="Permalink to &quot;`myco issue comment`&quot;">​</a></h2><p>Append a dated note under <code>## Comments</code> (created when missing)</p><p><strong>Usage:</strong> <code>myco issue comment &lt;ID&gt; &lt;TEXT&gt;</code></p><h6 id="arguments-8" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-8" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Issue id (<code>I-NNN</code>)</li><li><code>&lt;TEXT&gt;</code> — Comment text</li></ul><h2 id="myco-proposal" tabindex="-1"><code>myco proposal</code> <a class="header-anchor" href="#myco-proposal" aria-label="Permalink to &quot;`myco proposal`&quot;">​</a></h2><p>Design proposals under <code>proposals/</code> (<code>P-NNN</code>)</p><p><strong>Usage:</strong> <code>myco proposal &lt;COMMAND&gt;</code></p><h6 id="subcommands-4" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-4" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>new</code> — File a proposal — allocs a P-id, writes the proposal file with frontmatter + template</li><li><code>list</code> — List proposals</li><li><code>status</code> — Set a proposal&#39;s status. Proposal words alias the state machine: <code>draft</code> = open, <code>accepted</code> = done, <code>rejected</code> = deferred — the transition is walked through the machine, so <code>accepted</code> passes <code>open → in-progress → done</code></li></ul><h2 id="myco-proposal-new" tabindex="-1"><code>myco proposal new</code> <a class="header-anchor" href="#myco-proposal-new" aria-label="Permalink to &quot;`myco proposal new`&quot;">​</a></h2><p>File a proposal — allocs a P-id, writes the proposal file with frontmatter + template</p><p><strong>Usage:</strong> <code>myco proposal new [OPTIONS] &lt;TITLE&gt;</code></p><h6 id="arguments-9" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-9" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TITLE&gt;</code> — One-line title (drives the filename slug)</li></ul><h6 id="options-10" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-10" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--body &lt;FILE|-&gt;</code> — Body markdown from a file, or <code>-</code> for stdin</li><li><code>--text &lt;TEXT&gt;</code> — Body markdown inline</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id (<code>devin</code>, <code>human:luis</code>, …)</li><li><code>--label &lt;LABEL&gt;</code> — <code>#label</code> — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Ids this item blocks — comma-separated or repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — the delivery grouping this item belongs to (<code>[A-Za-z0-9_.-]+</code>)</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — the target this item ships under (<code>[A-Za-z0-9_.-]+</code>)</li></ul><h2 id="myco-proposal-list" tabindex="-1"><code>myco proposal list</code> <a class="header-anchor" href="#myco-proposal-list" aria-label="Permalink to &quot;`myco proposal list`&quot;">​</a></h2><p>List proposals</p><p><strong>Usage:</strong> <code>myco proposal list [OPTIONS]</code></p><h6 id="options-11" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-11" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--status &lt;STATUS&gt;</code> — Keep only items with this status</li><li><code>--owner &lt;OWNER&gt;</code> — Keep only items owned by this actor</li><li><code>--label &lt;LABEL&gt;</code> — Keep only items carrying all of these labels (repeatable)</li><li><code>--limit &lt;N&gt;</code> — Keep only the first N items after filtering</li></ul><h2 id="myco-proposal-status" tabindex="-1"><code>myco proposal status</code> <a class="header-anchor" href="#myco-proposal-status" aria-label="Permalink to &quot;`myco proposal status`&quot;">​</a></h2><p>Set a proposal&#39;s status. Proposal words alias the state machine: <code>draft</code> = open, <code>accepted</code> = done, <code>rejected</code> = deferred — the transition is walked through the machine, so <code>accepted</code> passes <code>open → in-progress → done</code></p><p><strong>Usage:</strong> <code>myco proposal status &lt;ID&gt; &lt;STATUS&gt;</code></p><h6 id="arguments-10" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-10" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Proposal id (<code>P-NNN</code>)</li><li><code>&lt;STATUS&gt;</code> — <code>draft</code> | <code>accepted</code> | <code>rejected</code> (raw machine statuses like <code>in-progress</code> also accepted)</li></ul><h2 id="myco-plan" tabindex="-1"><code>myco plan</code> <a class="header-anchor" href="#myco-plan" aria-label="Permalink to &quot;`myco plan`&quot;">​</a></h2><p>Execution plans under <code>plans/</code> (<code>PL-NNN</code>)</p><p><strong>Usage:</strong> <code>myco plan &lt;COMMAND&gt;</code></p><h6 id="subcommands-5" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-5" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>new</code> — File a plan — allocs a PL-id, writes the plan file with frontmatter + a phase-checklist template</li><li><code>list</code> — List plans</li></ul><h2 id="myco-plan-new" tabindex="-1"><code>myco plan new</code> <a class="header-anchor" href="#myco-plan-new" aria-label="Permalink to &quot;`myco plan new`&quot;">​</a></h2><p>File a plan — allocs a PL-id, writes the plan file with frontmatter + a phase-checklist template</p><p><strong>Usage:</strong> <code>myco plan new [OPTIONS] &lt;TITLE&gt;</code></p><h6 id="arguments-11" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-11" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TITLE&gt;</code> — One-line title (drives the filename slug)</li></ul><h6 id="options-12" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-12" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--body &lt;FILE|-&gt;</code> — Body markdown from a file, or <code>-</code> for stdin</li><li><code>--text &lt;TEXT&gt;</code> — Body markdown inline</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id (<code>devin</code>, <code>human:luis</code>, …)</li><li><code>--label &lt;LABEL&gt;</code> — <code>#label</code> — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Ids this item blocks — comma-separated or repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — the delivery grouping this item belongs to (<code>[A-Za-z0-9_.-]+</code>)</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — the target this item ships under (<code>[A-Za-z0-9_.-]+</code>)</li></ul><h2 id="myco-plan-list" tabindex="-1"><code>myco plan list</code> <a class="header-anchor" href="#myco-plan-list" aria-label="Permalink to &quot;`myco plan list`&quot;">​</a></h2><p>List plans</p><p><strong>Usage:</strong> <code>myco plan list [OPTIONS]</code></p><h6 id="options-13" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-13" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--status &lt;STATUS&gt;</code> — Keep only items with this status</li><li><code>--owner &lt;OWNER&gt;</code> — Keep only items owned by this actor</li><li><code>--label &lt;LABEL&gt;</code> — Keep only items carrying all of these labels (repeatable)</li><li><code>--limit &lt;N&gt;</code> — Keep only the first N items after filtering</li></ul><h2 id="myco-adr" tabindex="-1"><code>myco adr</code> <a class="header-anchor" href="#myco-adr" aria-label="Permalink to &quot;`myco adr`&quot;">​</a></h2><p>Architecture decision records under <code>adrs/</code> (<code>ADR-NNNN</code>)</p><p><strong>Usage:</strong> <code>myco adr &lt;COMMAND&gt;</code></p><h6 id="subcommands-6" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-6" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>new</code> — File an ADR — allocs an ADR-id, writes the file with frontmatter (status <code>open</code> = &quot;proposed&quot;) + template</li><li><code>list</code> — List ADRs</li><li><code>supersede</code> — Mark an ADR superseded by another — the old file gets <code>superseded_by:</code> + status <code>done</code>, the replacement gets a reciprocal <code>supersedes:</code> key. Both must already exist</li></ul><h2 id="myco-adr-new" tabindex="-1"><code>myco adr new</code> <a class="header-anchor" href="#myco-adr-new" aria-label="Permalink to &quot;`myco adr new`&quot;">​</a></h2><p>File an ADR — allocs an ADR-id, writes the file with frontmatter (status <code>open</code> = &quot;proposed&quot;) + template</p><p><strong>Usage:</strong> <code>myco adr new [OPTIONS] &lt;TITLE&gt;</code></p><h6 id="arguments-12" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-12" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;TITLE&gt;</code> — One-line title (drives the filename slug)</li></ul><h6 id="options-14" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-14" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--body &lt;FILE|-&gt;</code> — Body markdown from a file, or <code>-</code> for stdin</li><li><code>--text &lt;TEXT&gt;</code> — Body markdown inline</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id (<code>devin</code>, <code>human:luis</code>, …)</li><li><code>--label &lt;LABEL&gt;</code> — <code>#label</code> — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Ids this item blocks — comma-separated or repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — the delivery grouping this item belongs to (<code>[A-Za-z0-9_.-]+</code>)</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — the target this item ships under (<code>[A-Za-z0-9_.-]+</code>)</li></ul><h2 id="myco-adr-list" tabindex="-1"><code>myco adr list</code> <a class="header-anchor" href="#myco-adr-list" aria-label="Permalink to &quot;`myco adr list`&quot;">​</a></h2><p>List ADRs</p><p><strong>Usage:</strong> <code>myco adr list [OPTIONS]</code></p><h6 id="options-15" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-15" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--status &lt;STATUS&gt;</code> — Keep only items with this status</li><li><code>--owner &lt;OWNER&gt;</code> — Keep only items owned by this actor</li><li><code>--label &lt;LABEL&gt;</code> — Keep only items carrying all of these labels (repeatable)</li><li><code>--limit &lt;N&gt;</code> — Keep only the first N items after filtering</li></ul><h2 id="myco-adr-supersede" tabindex="-1"><code>myco adr supersede</code> <a class="header-anchor" href="#myco-adr-supersede" aria-label="Permalink to &quot;`myco adr supersede`&quot;">​</a></h2><p>Mark an ADR superseded by another — the old file gets <code>superseded_by:</code> + status <code>done</code>, the replacement gets a reciprocal <code>supersedes:</code> key. Both must already exist</p><p><strong>Usage:</strong> <code>myco adr supersede --by &lt;BY&gt; &lt;ID&gt;</code></p><h6 id="arguments-13" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-13" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — The ADR being replaced (<code>ADR-NNNN</code>)</li></ul><h6 id="options-16" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-16" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--by &lt;BY&gt;</code> — The ADR replacing it (<code>ADR-NNNN</code>)</li></ul><h2 id="myco-item" tabindex="-1"><code>myco item</code> <a class="header-anchor" href="#myco-item" aria-label="Permalink to &quot;`myco item`&quot;">​</a></h2><p>Kind-agnostic item verbs — show / set</p><p><strong>Usage:</strong> <code>myco item &lt;COMMAND&gt;</code></p><h6 id="subcommands-7" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-7" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>show</code> — Dump one item — frontmatter fields plus the body for file-backed kinds (<code>--json</code> = the full Item + location + body)</li><li><code>set</code> — Mutate an item in place. <code>--status</code> is the only field routed through the state machine — single steps only, invalid ones error with the valid targets. Status changes on tasks move the line between TODO.md and BACKLOG.md (<code>done</code> deletes it)</li></ul><h2 id="myco-item-show" tabindex="-1"><code>myco item show</code> <a class="header-anchor" href="#myco-item-show" aria-label="Permalink to &quot;`myco item show`&quot;">​</a></h2><p>Dump one item — frontmatter fields plus the body for file-backed kinds (<code>--json</code> = the full Item + location + body)</p><p><strong>Usage:</strong> <code>myco item show &lt;ID&gt;</code></p><h6 id="arguments-14" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-14" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Any item id (<code>T-NNN</code>, <code>I-NNN</code>, <code>P-NNN</code>, <code>ADR-NNNN</code>, <code>PL-NNN</code>) — live or archived</li></ul><h2 id="myco-item-set" tabindex="-1"><code>myco item set</code> <a class="header-anchor" href="#myco-item-set" aria-label="Permalink to &quot;`myco item set`&quot;">​</a></h2><p>Mutate an item in place. <code>--status</code> is the only field routed through the state machine — single steps only, invalid ones error with the valid targets. Status changes on tasks move the line between TODO.md and BACKLOG.md (<code>done</code> deletes it)</p><p><strong>Usage:</strong> <code>myco item set [OPTIONS] &lt;ID&gt;</code></p><h6 id="arguments-15" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-15" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Any item id</li></ul><h6 id="options-17" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-17" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--status &lt;STATUS&gt;</code> — New status — one legal step from the current one</li><li><code>--pri &lt;PRI&gt;</code> [alias: <code>priority</code>] — Priority: low|med|high|crit</li><li><code>--owner &lt;OWNER&gt;</code> — Owner actor id</li><li><code>--label &lt;LABEL&gt;</code> — Add (<code>+x</code> or <code>x</code>) or remove (<code>-x</code>) a label — repeatable</li><li><code>--unlabel &lt;UNLABEL&gt;</code> — Remove a label — repeatable</li><li><code>--blocks &lt;BLOCKS&gt;</code> — Add (<code>+T-1</code> or <code>T-1</code>) or remove (<code>-T-1</code>) a blocks dep — repeatable</li><li><code>--unblock &lt;UNBLOCK&gt;</code> — Remove a blocks dep — repeatable</li><li><code>--epic &lt;EPIC&gt;</code> — Epic name — <code>&quot;&quot;</code> clears the epic</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Milestone name — <code>&quot;&quot;</code> clears the milestone</li></ul><h2 id="myco-handoff" tabindex="-1"><code>myco handoff</code> <a class="header-anchor" href="#myco-handoff" aria-label="Permalink to &quot;`myco handoff`&quot;">​</a></h2><p>Attach resumable state at session end — appends a dated entry to <code>handoffs/&lt;ID&gt;.md</code> (any item kind, live or archived; append-only)</p><p><strong>Usage:</strong> <code>myco handoff [OPTIONS] --note &lt;TEXT|-&gt; &lt;ID&gt;</code></p><h6 id="arguments-16" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-16" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Any item id (<code>T-NNN</code>, <code>I-NNN</code>, <code>P-NNN</code>, <code>ADR-NNNN</code>, <code>PL-NNN</code>)</li></ul><h6 id="options-18" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-18" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--note &lt;TEXT|-&gt;</code> — Handoff note — done/next/open. <code>-</code> reads stdin</li><li><code>--actor &lt;ACTOR&gt;</code> — Who wrote it (<code>devin</code>, <code>human:luis</code>, …; default <code>cli</code>)</li><li><code>--session &lt;SESSION&gt;</code> — Session provenance — a sepia session id, <code>cli:&lt;pid&gt;</code>, any id string</li></ul><h2 id="myco-interrupt" tabindex="-1"><code>myco interrupt</code> <a class="header-anchor" href="#myco-interrupt" aria-label="Permalink to &quot;`myco interrupt`&quot;">​</a></h2><p>A session ended with work still claimed/in-progress/ blocked — revert the item to <code>open</code> + <code>interrupted</code> handoff, one commit. Session-lifecycle hooks (sepia, CLI session-end) call this; myco never detects sessions itself</p><p><strong>Usage:</strong> <code>myco interrupt [OPTIONS] &lt;ID&gt;</code></p><h6 id="arguments-17" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-17" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Any item id (<code>T-NNN</code>, <code>I-NNN</code>, <code>P-NNN</code>, <code>ADR-NNNN</code>, <code>PL-NNN</code>)</li></ul><h6 id="options-19" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-19" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--note &lt;TEXT&gt;</code> — Extra context appended to the <code>interrupted</code> note</li><li><code>--actor &lt;ACTOR&gt;</code> — Who interrupted it (default <code>cli</code>)</li><li><code>--session &lt;SESSION&gt;</code> — Session provenance — a sepia session id, <code>cli:&lt;pid&gt;</code>, any id string</li></ul><h2 id="myco-resume" tabindex="-1"><code>myco resume</code> <a class="header-anchor" href="#myco-resume" aria-label="Permalink to &quot;`myco resume`&quot;">​</a></h2><p>Minimal context block to restart work on an item — the item, <code>blocks:</code> dep titles, latest handoffs, open checklist. The single-item <code>status --prompt</code></p><p><strong>Usage:</strong> <code>myco resume [OPTIONS] &lt;ID&gt;</code></p><h6 id="arguments-18" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-18" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;ID&gt;</code> — Any item id</li></ul><h6 id="options-20" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-20" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--last &lt;LAST&gt;</code> — Only the latest N handoff entries (default 10)</li></ul><h2 id="myco-status" tabindex="-1"><code>myco status</code> <a class="header-anchor" href="#myco-status" aria-label="Permalink to &quot;`myco status`&quot;">​</a></h2><p>Cheap digest of the work ledger. <code>--prompt</code> = token-sized</p><p><strong>Usage:</strong> <code>myco status [OPTIONS]</code></p><h6 id="options-21" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-21" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--prompt</code> — Render for an agent prompt (minimal tokens)</li></ul><h2 id="myco-board" tabindex="-1"><code>myco board</code> <a class="header-anchor" href="#myco-board" aria-label="Permalink to &quot;`myco board`&quot;">​</a></h2><p>Kanban of the ledger — Backlog | Open | Claimed | In Progress | Blocked. <code>--md</code> emits a markdown table</p><p><strong>Usage:</strong> <code>myco board [OPTIONS]</code></p><h6 id="options-22" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-22" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--md</code> — Emit a markdown table (for docs/READMEs)</li><li><code>--all</code> — Show every card — no row cap</li><li><code>--epic &lt;EPIC&gt;</code> — Only items in this epic</li><li><code>--milestone &lt;MILESTONE&gt;</code> — Only items in this milestone</li></ul><h2 id="myco-epic" tabindex="-1"><code>myco epic</code> <a class="header-anchor" href="#myco-epic" aria-label="Permalink to &quot;`myco epic`&quot;">​</a></h2><p>Items grouped by epic — bare lists epics with counts, a name renders that epic&#39;s board (<code>epic v2</code> ≡ <code>board --epic v2</code>)</p><p><strong>Usage:</strong> <code>myco epic [OPTIONS] [NAME]</code></p><h6 id="arguments-19" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-19" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;NAME&gt;</code> — Epic name — omit for the all-epics summary</li></ul><h6 id="options-23" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-23" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--md</code> — Emit a markdown table (with a name)</li><li><code>--all</code> — Show every card — no row cap (with a name)</li></ul><h2 id="myco-milestone" tabindex="-1"><code>myco milestone</code> <a class="header-anchor" href="#myco-milestone" aria-label="Permalink to &quot;`myco milestone`&quot;">​</a></h2><p>Items grouped by milestone — bare lists milestones with counts, a name renders that milestone&#39;s board</p><p><strong>Usage:</strong> <code>myco milestone [OPTIONS] [NAME]</code></p><h6 id="arguments-20" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-20" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;NAME&gt;</code> — Milestone name — omit for the all-milestones summary</li></ul><h6 id="options-24" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-24" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--md</code> — Emit a markdown table (with a name)</li><li><code>--all</code> — Show every card — no row cap (with a name)</li></ul><h2 id="myco-absorb" tabindex="-1"><code>myco absorb</code> <a class="header-anchor" href="#myco-absorb" aria-label="Permalink to &quot;`myco absorb`&quot;">​</a></h2><p>Import work into the ledger — TODO/FIXME comments, Jira CSV exports, GitHub issue dumps</p><p><strong>Usage:</strong> <code>myco absorb &lt;COMMAND&gt;</code></p><h6 id="subcommands-8" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-8" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>comments</code> — Sweep code comments into the ledger via ripgrep (<code>rg</code> must be installed — respects <code>.gitignore</code>; <code>project/</code>, <code>docs/</code>, <code>target/</code> are excluded)</li><li><code>jira</code> — Import a Jira CSV export. <code>Done</code>/<code>Resolved</code> rows are skipped unless <code>--include-done</code> (created done + archived)</li><li><code>github</code> — Import a GitHub issues dump — a JSON array (<code>number</code>, <code>title</code>, <code>state</code>, <code>labels</code>, <code>assignee</code>, <code>body</code>) or the CSV equivalent. <code>closed</code> rows are skipped unless <code>--include-done</code> (created done + archived)</li></ul><h2 id="myco-absorb-comments" tabindex="-1"><code>myco absorb comments</code> <a class="header-anchor" href="#myco-absorb-comments" aria-label="Permalink to &quot;`myco absorb comments`&quot;">​</a></h2><p>Sweep code comments into the ledger via ripgrep (<code>rg</code> must be installed — respects <code>.gitignore</code>; <code>project/</code>, <code>docs/</code>, <code>target/</code> are excluded)</p><p><strong>Usage:</strong> <code>myco absorb comments [OPTIONS]</code></p><h6 id="options-25" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-25" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><p><code>--path &lt;PATH&gt;</code> — Directory to scan (default: the repo root)</p></li><li><p><code>--kinds &lt;KINDS&gt;</code> — Comment kinds to match — comma-separated or repeatable (default TODO,FIXME,HACK)</p></li><li><p><code>--to &lt;TO&gt;</code> — Where findings land: <code>backlog</code> items or <code>issues</code> files (default <code>backlog</code>)</p><p>Default value: <code>backlog</code></p></li><li><p><code>--dry</code> — Report findings without creating items or committing</p></li></ul><h2 id="myco-absorb-jira" tabindex="-1"><code>myco absorb jira</code> <a class="header-anchor" href="#myco-absorb-jira" aria-label="Permalink to &quot;`myco absorb jira`&quot;">​</a></h2><p>Import a Jira CSV export. <code>Done</code>/<code>Resolved</code> rows are skipped unless <code>--include-done</code> (created done + archived)</p><p><strong>Usage:</strong> <code>myco absorb jira [OPTIONS] &lt;FILE&gt;</code></p><h6 id="arguments-21" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-21" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;FILE&gt;</code> — The export file (<code>.csv</code>)</li></ul><h6 id="options-26" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-26" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--include-done</code> — Import done/resolved issues too</li></ul><h2 id="myco-absorb-github" tabindex="-1"><code>myco absorb github</code> <a class="header-anchor" href="#myco-absorb-github" aria-label="Permalink to &quot;`myco absorb github`&quot;">​</a></h2><p>Import a GitHub issues dump — a JSON array (<code>number</code>, <code>title</code>, <code>state</code>, <code>labels</code>, <code>assignee</code>, <code>body</code>) or the CSV equivalent. <code>closed</code> rows are skipped unless <code>--include-done</code> (created done + archived)</p><p><strong>Usage:</strong> <code>myco absorb github [OPTIONS] &lt;FILE&gt;</code></p><h6 id="arguments-22" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-22" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;FILE&gt;</code> — The export file (<code>.json</code> or <code>.csv</code>)</li></ul><h6 id="options-27" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-27" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--include-done</code> — Import closed issues too</li></ul><h2 id="myco-report" tabindex="-1"><code>myco report</code> <a class="header-anchor" href="#myco-report" aria-label="Permalink to &quot;`myco report`&quot;">​</a></h2><p>Aging + velocity + blocked — how the ledger is trending</p><p><strong>Usage:</strong> <code>myco report</code></p><h2 id="myco-index" tabindex="-1"><code>myco index</code> <a class="header-anchor" href="#myco-index" aria-label="Permalink to &quot;`myco index`&quot;">​</a></h2><p>The derived index: register repos, query/rebuild snapshots</p><p><strong>Usage:</strong> <code>myco index &lt;COMMAND&gt;</code></p><h6 id="subcommands-9" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-9" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>add</code> — Register a repo — <code>&lt;path&gt;</code> is a repo root (or its <code>project/</code> worktree). Takes an initial snapshot</li><li><code>remove</code> — Unregister a repo and drop its snapshot</li><li><code>list</code> — List registered repos with snapshot freshness</li><li><code>rebuild</code> — Re-scan a registered repo (all of them without <code>&lt;path&gt;</code>)</li></ul><h2 id="myco-index-add" tabindex="-1"><code>myco index add</code> <a class="header-anchor" href="#myco-index-add" aria-label="Permalink to &quot;`myco index add`&quot;">​</a></h2><p>Register a repo — <code>&lt;path&gt;</code> is a repo root (or its <code>project/</code> worktree). Takes an initial snapshot</p><p><strong>Usage:</strong> <code>myco index add &lt;PATH&gt;</code></p><h6 id="arguments-23" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-23" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;PATH&gt;</code> — Repo root (or project worktree) to register</li></ul><h2 id="myco-index-remove" tabindex="-1"><code>myco index remove</code> <a class="header-anchor" href="#myco-index-remove" aria-label="Permalink to &quot;`myco index remove`&quot;">​</a></h2><p>Unregister a repo and drop its snapshot</p><p><strong>Usage:</strong> <code>myco index remove &lt;PATH&gt;</code></p><h6 id="arguments-24" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-24" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;PATH&gt;</code> — Registered repo root (or project worktree)</li></ul><h2 id="myco-index-list" tabindex="-1"><code>myco index list</code> <a class="header-anchor" href="#myco-index-list" aria-label="Permalink to &quot;`myco index list`&quot;">​</a></h2><p>List registered repos with snapshot freshness</p><p><strong>Usage:</strong> <code>myco index list</code></p><h2 id="myco-index-rebuild" tabindex="-1"><code>myco index rebuild</code> <a class="header-anchor" href="#myco-index-rebuild" aria-label="Permalink to &quot;`myco index rebuild`&quot;">​</a></h2><p>Re-scan a registered repo (all of them without <code>&lt;path&gt;</code>)</p><p><strong>Usage:</strong> <code>myco index rebuild [PATH]</code></p><h6 id="arguments-25" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments-25" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;PATH&gt;</code> — Registered repo root (or project worktree)</li></ul><h2 id="myco-org" tabindex="-1"><code>myco org</code> <a class="header-anchor" href="#myco-org" aria-label="Permalink to &quot;`myco org`&quot;">​</a></h2><p>Cross-repo views over the index (auto-rebuilds stale repos)</p><p><strong>Usage:</strong> <code>myco org &lt;COMMAND&gt;</code></p><h6 id="subcommands-10" tabindex="-1"><strong>Subcommands:</strong> <a class="header-anchor" href="#subcommands-10" aria-label="Permalink to &quot;**Subcommands:**&quot;">​</a></h6><ul><li><code>status</code> — Per-repo counts + org totals + items grouped by owner</li><li><code>board</code> — Org kanban — repo-prefixed cards over every live item</li><li><code>init</code> — Re-run <code>init</code> on every registered repo — refreshes the worktree scaffold and root files (.gitignore, the AGENTS.md agent-awareness block). The rollout path for new scaffolding</li></ul><h2 id="myco-org-status" tabindex="-1"><code>myco org status</code> <a class="header-anchor" href="#myco-org-status" aria-label="Permalink to &quot;`myco org status`&quot;">​</a></h2><p>Per-repo counts + org totals + items grouped by owner</p><p><strong>Usage:</strong> <code>myco org status [OPTIONS]</code></p><h6 id="options-28" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-28" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--all</code> — Show repos with no live items too</li></ul><h2 id="myco-org-board" tabindex="-1"><code>myco org board</code> <a class="header-anchor" href="#myco-org-board" aria-label="Permalink to &quot;`myco org board`&quot;">​</a></h2><p>Org kanban — repo-prefixed cards over every live item</p><p><strong>Usage:</strong> <code>myco org board [OPTIONS]</code></p><h6 id="options-29" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-29" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--md</code> — Emit a markdown table (for docs/READMEs)</li><li><code>--all</code> — Show every card — no row cap</li><li><code>--repo &lt;REPO&gt;</code> — Only this repo&#39;s items (name or registered path)</li></ul><h2 id="myco-org-init" tabindex="-1"><code>myco org init</code> <a class="header-anchor" href="#myco-org-init" aria-label="Permalink to &quot;`myco org init`&quot;">​</a></h2><p>Re-run <code>init</code> on every registered repo — refreshes the worktree scaffold and root files (.gitignore, the AGENTS.md agent-awareness block). The rollout path for new scaffolding</p><p><strong>Usage:</strong> <code>myco org init</code></p><h2 id="myco-ui" tabindex="-1"><code>myco ui</code> <a class="header-anchor" href="#myco-ui" aria-label="Permalink to &quot;`myco ui`&quot;">​</a></h2><p>Interactive board TUI (ratatui) — TODO/BACKLOG tabs, item preview, writes through the same ops the verbs use</p><p><strong>Usage:</strong> <code>myco ui</code></p><h2 id="myco-serve" tabindex="-1"><code>myco serve</code> <a class="header-anchor" href="#myco-serve" aria-label="Permalink to &quot;`myco serve`&quot;">​</a></h2><p>Sequential request/response verb surface on stdio — JSON-RPC 2.0, one line in / one line out. For embedding (peregrin spawns one per repo); stdin IS the wire, so no served method reads content from it</p><p><strong>Usage:</strong> <code>myco serve</code></p><hr><p><small><i> This document was generated automatically by <a href="https://crates.io/crates/clap-markdown"><code>clap-markdown</code></a>. </i></small></p>',317)])])}const u=o(c,[["render",i]]);export{p as __pageData,u as default};
